return [{ json: {} }];

const headers = $input.first().json.headers || {};
const authHeader = headers['authorization'] || headers['Authorization'] || '';
const token = authHeader.replace('Bearer ', '').trim();
const match = token.match(/^token_(\d+)_(\d+)$/);
if (!match) throw new Error('Invalid or missing session token.');
return [{ json: { requesterId: parseInt(match[1], 10) } }];

const requester = $input.first().json;
const body = $('Webhook - Save Automation').first().json.body || {};
if (!requester.id || !requester.active) throw new Error('Invalid session.');

const VALID_TRIGGER_TYPES = ['contact', 'company', 'task', 'calendar', 'pipeline'];
const VALID_ACTION_TYPES = ['add_tag', 'send_email', 'send_team_notification', 'send_sms', 'wait', 'update_field', 'branch_if', 'assign_owner_round_robin', 'send_dm', 'enroll_nurture'];
// 'created' (webhook-triggered) and 'inactive' (schedule-triggered, polls
// on its own dedicated Schedule Trigger) are compiler-supported today.
const VALID_TRIGGER_EVENTS = ['created', 'inactive'];

const id = body.id ? parseInt(body.id, 10) : null;
const name = (body.name || '').toString().trim();
const triggerType = (body.trigger_type || '').toString();
if (!name) throw new Error('"name" is required.');
if (!VALID_TRIGGER_TYPES.includes(triggerType)) throw new Error('"trigger_type" is invalid.');

const triggerEvent = body.trigger_event ? body.trigger_event.toString() : null;
if (triggerEvent && !VALID_TRIGGER_EVENTS.includes(triggerEvent)) throw new Error('"trigger_event" is invalid.');

// 'created' doesn't use the old field/operator/value condition at all — the
// event itself is the trigger. Everything else (no event, or 'inactive',
// which uses trigger_config to express "N days since last activity") keeps
// requiring a fully configured condition, exactly as before.
const triggerConfig = body.trigger_config || {};
if (triggerEvent !== 'created' && (!triggerConfig.field || !triggerConfig.operator || triggerConfig.value === undefined || triggerConfig.value === '')) {
  throw new Error('A fully configured trigger is required.');
}

const conditionTree = (body.condition_tree && body.condition_tree.field) ? body.condition_tree : null;

const rawActions = Array.isArray(body.actions) ? body.actions : [];
if (rawActions.length === 0) throw new Error('At least one action is required.');
const actions = rawActions.map((a, i) => {
  if (!VALID_ACTION_TYPES.includes(a.action_type)) throw new Error(`Action ${i + 1}: invalid action_type.`);
  return {
    branch: (a.branch || 'default').toString(),
    action_type: a.action_type,
    action_config: a.action_config || {},
    sort_order: i,
  };
});

return [{ json: { id, name, triggerType, triggerEvent, triggerConfig, conditionTree, actions, requesterId: requester.id } }];

