const automationId = $('Upsert Automation').first().json.id;
const actions = $('Validate & Payload (Save)').first().json.actions;
return actions.map((a) => ({ json: { automationId, ...a } }));

const triggerType = $('Validate & Payload (Save)').first().json.triggerType;
const triggerEvent = $('Validate & Payload (Save)').first().json.triggerEvent;
return [{ json: {
  automationId: $('Upsert Automation').first().json.id,
  triggerType,
  triggerEvent,
  shouldCompile: triggerType === 'contact' && ['created', 'inactive'].includes(triggerEvent),
} }];

const automationId = $('Prepare Compile Check').first().json.automationId;
const res = $input.first().json;
// Connection-level failure (compiler-server.cjs not running at all) lands
// here as an n8n HTTP node error object; a reachable-but-failed compile
// lands as { success: false, error }. Both should degrade the same way —
// the automation still saved, it's just not compiled to a live workflow.
if (res.error && typeof res.error === 'object') {
  return [{ json: { success: true, id: automationId, compiled: false, compile_error: (res.error.message || 'Compiler unreachable — is compiler-server.cjs running?') } }];
}
if (res.success === false) {
  return [{ json: { success: true, id: automationId, compiled: false, compile_error: res.error || 'Compile failed.' } }];
}
return [{ json: { success: true, id: automationId, compiled: true, n8n_workflow_id: res.n8n_workflow_id } }];

const headers = $input.first().json.headers || {};
const authHeader = headers['authorization'] || headers['Authorization'] || '';
const token = authHeader.replace('Bearer ', '').trim();
const match = token.match(/^token_(\d+)_(\d+)$/);
if (!match) throw new Error('Invalid or missing session token.');
return [{ json: { requesterId: parseInt(match[1], 10) } }];

const requester = $input.first().json;
const body = $('Webhook - Update Automation Active').first().json.body || {};
if (!requester.id || !requester.active) throw new Error('Invalid session.');
const id = parseInt(body.id, 10);
if (!Number.isInteger(id)) throw new Error('"id" must be an integer.');
if (typeof body.is_active !== 'boolean') throw new Error('"is_active" must be true or false.');
return [{ json: { id, isActive: body.is_active } }];

const result = $input.first();
if (!result || !result.json || !result.json.id) throw new Error('Automation not found.');
return [{ json: { success: true } }];

const headers = $input.first().json.headers || {};
const authHeader = headers['authorization'] || headers['Authorization'] || '';
const token = authHeader.replace('Bearer ', '').trim();
const match = token.match(/^token_(\d+)_(\d+)$/);
if (!match) throw new Error('Invalid or missing session token.');
return [{ json: { requesterId: parseInt(match[1], 10) } }];

const requester = $input.first().json;
const body = $('Webhook - Delete Automation').first().json.body || {};
if (!requester.id || !requester.active) throw new Error('Invalid session.');
const id = parseInt(body.id, 10);
if (!Number.isInteger(id)) throw new Error('"id" must be an integer.');
return [{ json: { id } }];

const result = $input.first();
if (!result || !result.json || !result.json.id) throw new Error('Automation not found.');
return [{ json: { success: true } }];

const headers = $input.first().json.headers || {};
const authHeader = headers['authorization'] || headers['Authorization'] || '';
const token = authHeader.replace('Bearer ', '').trim();
const match = token.match(/^token_(\d+)_(\d+)$/);
if (!match) throw new Error('Invalid or missing session token.');
return [{ json: { requesterId: parseInt(match[1], 10) } }];

const requester = $input.first().json;
const body = $('Webhook - Test Automation').first().json.body || {};
if (!requester.id || !requester.active) throw new Error('Invalid session.');

const VALID_TRIGGER_TYPES = ['contact', 'company', 'task', 'calendar', 'pipeline'];
const VALID_ACTION_TYPES = ['add_tag', 'send_email', 'send_team_notification', 'send_sms', 'wait', 'update_field'];

const id = body.id ? parseInt(body.id, 10) : null;
const name = (body.name || '').toString().trim();
const triggerType = (body.trigger_type || '').toString();
if (!name) throw new Error('"name" is required.');
if (!VALID_TRIGGER_TYPES.includes(triggerType)) throw new Error('"trigger_type" is invalid.');

const triggerConfig = body.trigger_config;
if (!triggerConfig || !triggerConfig.field || !triggerConfig.operator || triggerConfig.value === undefined || triggerConfig.value === '') {
  throw new Error('A fully configured trigger is required.');
}

const conditionTree = (body.condition_tree && body.condition_tree.field) ? body.condition_tree : null;

const rawActions = Array.isArray(body.actions) ? body.actions : [];
if (rawActions.length === 0) throw new Error('At least one action is required.');
const actions = rawActions.map((a, i) => {
  if (!VALID_ACTION_TYPES.includes(a.action_type)) throw new Error(`Action ${i + 1}: invalid action_type.`);
  return {
    branch: (a.branch || 'default').toString(),
    action_type: a.action_type,
    action_config: a.action_config || {},
    sort_order: i,
  };
});

const testEmail = (body.test_email || '').toString().trim() || null;
return [{ json: { id, name, triggerType, triggerConfig, conditionTree, actions, testEmail, requesterId: requester.id } }];

const rows = $input.all().map((i) => i.json);
const p = $('Validate & Payload (Test)').first().json;
const trigger = p.triggerConfig;
const condition = p.conditionTree;
const actions = p.actions;

function getFieldValue(row, field) {
  if (field === 'age') {
    if (!row.birthdate) return null;
    const ms = Date.now() - new Date(row.birthdate).getTime();
    return Math.floor(ms / (365.25 * 24 * 3600 * 1000));
  }
  if (field === 'overdue') {
    return !row.is_completed && row.due_at && new Date(row.due_at) < new Date();
  }
  if (field === 'location') {
    return [row.city, row.state, row.country].filter(Boolean).join(', ');
  }
  if (field === 'days_since_stage_entered') {
    if (!row.stage_entered_at) return null;
    return Math.floor((Date.now() - new Date(row.stage_entered_at).getTime()) / 86400000);
  }
  if (field === 'days_since_last_activity') {
    if (!row.last_contacted_at) return null;
    return Math.floor((Date.now() - new Date(row.last_contacted_at).getTime()) / 86400000);
  }
  if (field === 'days_since_created') {
    if (!row.created_at) return null;
    return Math.floor((Date.now() - new Date(row.created_at).getTime()) / 86400000);
  }
  if (field === 'days_inactive') {
    if (!row.last_touched_at) return null;
    return Math.floor((Date.now() - new Date(row.last_touched_at).getTime()) / 86400000);
  }
  if (field === 'sla_overdue') {
    if (!row.sla_due_at || row.status === 'resolved' || row.status === 'closed') return false;
    return new Date(row.sla_due_at).getTime() < Date.now();
  }
  // Backed by contacts.email_logs — 'received' entries come from a live
  // Gmail-inbox poller (contacts-email-reply.json) that runs regardless of
  // which flow sent the original email, so replies are always accurate.
  // 'sent' entries only get an opened_at once the tracking pixel embedded
  // in that HTML email is actually loaded — many email clients block
  // remote images by default, so this is a best-effort signal, not a
  // guarantee an unopened result means truly unread.
  if (field === 'email_replied') {
    const logs = Array.isArray(row.email_logs) ? row.email_logs : [];
    const lastSent = logs.filter((l) => l && l.type === 'sent').sort((a, b) => new Date(b.sent_at) - new Date(a.sent_at))[0];
    const referenceTime = lastSent ? new Date(lastSent.sent_at).getTime() : 0;
    return logs.some((l) => l && l.type === 'received' && new Date(l.sent_at).getTime() > referenceTime);
  }
  if (field === 'email_opened') {
    const logs = Array.isArray(row.email_logs) ? row.email_logs : [];
    return logs.some((l) => l && l.type === 'sent' && l.opened_at);
  }
  if (field === 'days_since_proposal_sent') {
    if (!row.proposal_emailed_at) return null;
    return Math.floor((Date.now() - new Date(row.proposal_emailed_at).getTime()) / 86400000);
  }
  if (field === 'days_since_proposal_viewed') {
    if (!row.proposal_viewed_at) return null;
    return Math.floor((Date.now() - new Date(row.proposal_viewed_at).getTime()) / 86400000);
  }
  if (field === 'days_since_contract_sent') {
    if (!row.contract_sent_at) return null;
    return Math.floor((Date.now() - new Date(row.contract_sent_at).getTime()) / 86400000);
  }
  if (field === 'days_since_contract_signed') {
    if (!row.contract_signed_at) return null;
    return Math.floor((Date.now() - new Date(row.contract_signed_at).getTime()) / 86400000);
  }
  return row[field];
}

function evalCondition(row, cond) {
  if (!cond || !cond.field) return true;
  const actual = getFieldValue(row, cond.field);
  const expected = cond.value;
  switch (cond.operator) {
    case 'equals': return Array.isArray(actual) ? actual.includes(expected) : String(actual) === String(expected);
    case 'not_equals': return Array.isArray(actual) ? !actual.includes(expected) : String(actual) !== String(expected);
    case 'contains': return String(actual || '').toLowerCase().includes(String(expected).toLowerCase());
    case 'greater_than': { const n = Number(actual); return Number.isFinite(n) ? n > Number(expected) : new Date(actual) > new Date(expected); }
    case 'less_than': { const n = Number(actual); return Number.isFinite(n) ? n < Number(expected) : new Date(actual) < new Date(expected); }
    case 'is_true': return Boolean(actual) === true;
    case 'is_false': return Boolean(actual) === false;
    default: return false;
  }
}

let matched = null;
let branch = null;
for (const row of rows) {
  if (!evalCondition(row, trigger)) continue;
  matched = row;
  branch = condition ? (evalCondition(row, condition) ? 'true' : 'false') : 'default';
  break;
}

const actionsWouldRun = matched
  ? actions.filter((a) => a.branch === branch).map((a) => ({
      action_type: a.action_type,
      status: a.action_type === 'send_sms' ? 'unsupported' : 'would_run',
    }))
  : [];

const emailAction = matched ? (actions.filter((a) => a.branch === branch).find((a) => a.action_type === 'send_email') || null) : null;

return [{
  json: {
    matched: !!matched,
    branch,
    sample_entity: matched
      ? { id: matched.id, label: matched.name || [matched.first_name, matched.last_name].filter(Boolean).join(' ') || `#${matched.id}` }
      : null,
    actions_would_run: actionsWouldRun,
    test_email_sent: false,
    _shouldSendTestEmail: Boolean(p.testEmail) && Boolean(emailAction),
    _testEmail: p.testEmail || null,
    _matchedRow: matched,
    _emailAction: emailAction,
  },
}];

const meta = $('Evaluate & Respond').item.json;
const row = meta._matchedRow || {};
// Mirrors src/utils/text.ts's toTitleCase so a test send previews the
// same casing a real send would use, regardless of how the name is
// actually capitalized in the database.
function toTitleCase(s) {
  return (s || '').toString().toLowerCase().split(' ').map((w) => (w ? w[0].toUpperCase() + w.slice(1) : w)).join(' ');
}
function money(n) {
  return n != null && n !== '' ? '$' + Number(n).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 }) : '';
}
function dateStr(d) {
  return d ? new Date(d).toLocaleDateString() : '';
}
function dateTimeStr(d) {
  return d ? new Date(d).toLocaleString() : '';
}
const opp = meta.entityType === 'pipeline' ? row : {};
const appt = (meta.entityType === 'task' || meta.entityType === 'calendar') ? row : {};
function fill(template) {
  return (template || '')
    .replace(/{{\s*first_name\s*}}/gi, toTitleCase(row.first_name) || 'there')
    .replace(/{{\s*last_name\s*}}/gi, toTitleCase(row.last_name))
    .replace(/{{\s*deal_name\s*}}/gi, row.name || 'Sample Deal')
    .replace(/{{\s*owner_name\s*}}/gi, toTitleCase(row.owner_name) || 'your account team')
    .replace(/{{\s*proposal_link\s*}}/gi, row.proposal_token ? `#proposal-${row.proposal_token}` : '#')
    .replace(/{{\s*email\s*}}/gi, row.email || '')
    .replace(/{{\s*phone\s*}}/gi, row.phone || '')
    .replace(/{{\s*job_title\s*}}/gi, row.job_title || '')
    .replace(/{{\s*lead_status\s*}}/gi, row.lead_status || '')
    .replace(/{{\s*city\s*}}/gi, row.city || '')
    .replace(/{{\s*state\s*}}/gi, row.state || '')
    .replace(/{{\s*country\s*}}/gi, row.country || '')
    .replace(/{{\s*company_name\s*}}/gi, row.company_name || '')
    .replace(/{{\s*industry\s*}}/gi, row.industry || '')
    .replace(/{{\s*website\s*}}/gi, row.website || '')
    .replace(/{{\s*deal_value\s*}}/gi, money(row.deal_value))
    .replace(/{{\s*deal_stage\s*}}/gi, row.stage_name || '')
    .replace(/{{\s*pipeline_name\s*}}/gi, row.pipeline_name || '')
    .replace(/{{\s*expected_close\s*}}/gi, dateStr(row.expected_close))
    .replace(/{{\s*task_name\s*}}/gi, row.name || '')
    .replace(/{{\s*due_date\s*}}/gi, dateStr(row.due_at))
    .replace(/{{\s*event_type\s*}}/gi, row.event_type || '')
    .replace(/{{\s*owner_email\s*}}/gi, row.owner_email || '')
    .replace(/{{\s*owner_phone\s*}}/gi, row.owner_phone || '')
    .replace(/{{\s*contract_link\s*}}/gi, row.contract_token ? `#contract-${row.contract_token}` : '#')
    .replace(/{{\s*today\s*}}/gi, dateStr(new Date()))
    // Namespaced tokens (GHL-style) added alongside the original flat ones
    // above — both resolve the same underlying data, so every automation/
    // template saved before this addition keeps working untouched.
    .replace(/{{\s*contact\.id\s*}}/gi, row.contact_id != null ? String(row.contact_id) : '')
    .replace(/{{\s*contact\.first_name\s*}}/gi, toTitleCase(row.first_name))
    .replace(/{{\s*contact\.last_name\s*}}/gi, toTitleCase(row.last_name))
    .replace(/{{\s*contact\.full_name\s*}}/gi, toTitleCase(`${row.first_name || ''} ${row.last_name || ''}`.trim()))
    .replace(/{{\s*contact\.email\s*}}/gi, row.email || '')
    .replace(/{{\s*contact\.phone\s*}}/gi, row.phone || '')
    .replace(/{{\s*contact\.city\s*}}/gi, row.contact_city || '')
    .replace(/{{\s*contact\.state\s*}}/gi, row.contact_state || '')
    .replace(/{{\s*contact\.postal_code\s*}}/gi, row.contact_zip_code || '')
    .replace(/{{\s*contact\.country\s*}}/gi, row.contact_country || '')
    .replace(/{{\s*contact\.date_of_birth\s*}}/gi, dateStr(row.contact_birthdate))
    .replace(/{{\s*contact\.source\s*}}/gi, row.contact_lead_source || '')
    .replace(/{{\s*contact\.tags\s*}}/gi, Array.isArray(row.tags) ? row.tags.join(', ') : '')
    .replace(/{{\s*contact\.created_at\s*}}/gi, dateStr(row.contact_created_at))
    .replace(/{{\s*contact\.updated_at\s*}}/gi, dateStr(row.contact_updated_at))
    .replace(/{{\s*company\.id\s*}}/gi, row.company_id != null ? String(row.company_id) : '')
    .replace(/{{\s*company\.name\s*}}/gi, row.company_name || '')
    .replace(/{{\s*company\.phone\s*}}/gi, row.company_phone || '')
    .replace(/{{\s*company\.website\s*}}/gi, row.company_website || '')
    .replace(/{{\s*company\.address\s*}}/gi, row.company_street_address || '')
    .replace(/{{\s*company\.city\s*}}/gi, row.company_city || '')
    .replace(/{{\s*company\.state\s*}}/gi, row.company_state || '')
    .replace(/{{\s*company\.postal_code\s*}}/gi, row.company_zip_code || '')
    .replace(/{{\s*company\.country\s*}}/gi, row.company_country || '')
    // Opportunity fields only ever come from a Pipeline (Deal) trigger's own
    // row — on any other trigger type `opp` is `{}` so these all resolve to
    // '' instead of leaking a same-named column from the wrong entity (e.g.
    // a Ticket's `row.status` under a Contact/Task trigger).
    .replace(/{{\s*opportunity\.id\s*}}/gi, opp.id != null ? String(opp.id) : '')
    .replace(/{{\s*opportunity\.name\s*}}/gi, opp.name || '')
    .replace(/{{\s*opportunity\.status\s*}}/gi, opp.status || '')
    .replace(/{{\s*opportunity\.pipeline\s*}}/gi, opp.pipeline_name || '')
    .replace(/{{\s*opportunity\.pipeline_id\s*}}/gi, opp.pipeline_id != null ? String(opp.pipeline_id) : '')
    .replace(/{{\s*opportunity\.stage\s*}}/gi, opp.stage_name || '')
    .replace(/{{\s*opportunity\.stage_id\s*}}/gi, opp.stage_id != null ? String(opp.stage_id) : '')
    .replace(/{{\s*opportunity\.value\s*}}/gi, money(opp.deal_value))
    .replace(/{{\s*opportunity\.source\s*}}/gi, opp.source || '')
    .replace(/{{\s*opportunity\.created_at\s*}}/gi, dateStr(opp.created_at))
    .replace(/{{\s*opportunity\.updated_at\s*}}/gi, dateStr(opp.updated_at))
    // Appointment reuses Task/Calendar data (`activities`) — there is no
    // separate appointments table in this schema. Only resolves on those
    // two trigger types, same guard reasoning as Opportunity above.
    .replace(/{{\s*appointment\.id\s*}}/gi, appt.id != null ? String(appt.id) : '')
    .replace(/{{\s*appointment\.title\s*}}/gi, appt.name || '')
    .replace(/{{\s*appointment\.start_time\s*}}/gi, dateTimeStr(appt.start_at || appt.due_at))
    .replace(/{{\s*appointment\.end_time\s*}}/gi, dateTimeStr(appt.end_at))
    .replace(/{{\s*appointment\.status\s*}}/gi, appt.id != null ? (appt.is_completed ? 'Completed' : 'Not completed') : '')
    .replace(/{{\s*appointment\.calendar\s*}}/gi, appt.event_type || '')
    .replace(/{{\s*appointment\.location\s*}}/gi, appt.location || '')
    .replace(/{{\s*appointment\.assigned_user\s*}}/gi, appt.id != null ? (toTitleCase(row.owner_name) || '') : '')
    .replace(/{{\s*appointment\.notes\s*}}/gi, appt.notes || '')
    // User/Sales Rep — the record's owner/assigned user, already resolved
    // for every trigger type (same owner_* columns the flat tokens use).
    .replace(/{{\s*user\.id\s*}}/gi, row.owner_user_id != null ? String(row.owner_user_id) : '')
    .replace(/{{\s*user\.full_name\s*}}/gi, toTitleCase(row.owner_name) || 'your account team')
    .replace(/{{\s*user\.email\s*}}/gi, row.owner_email || '')
    .replace(/{{\s*user\.phone\s*}}/gi, row.owner_phone || '')
    // System — always resolvable, no row data involved.
    .replace(/{{\s*system\.current_date\s*}}/gi, dateStr(new Date()))
    .replace(/{{\s*system\.current_time\s*}}/gi, new Date().toLocaleTimeString())
    .replace(/{{\s*system\.current_datetime\s*}}/gi, dateTimeStr(new Date()))
    .replace(/{{\s*system\.timestamp\s*}}/gi, new Date().toISOString())
    // A real send clones the referenced template into an actual DB row via
    // Automation Engine.json — a Test send deliberately does NOT (this whole
    // flow is a dry run with no side effects), so these can't resolve to a
    // real link here. Show a clearly-labeled placeholder instead of silently
    // deleting the token via the generic {{ }} strip below, which is what
    // made proposal/contract links vanish from test sends entirely.
    .replace(/{{\s*proposal_template:\d+\s*}}/gi, '[TEST — a real, unique proposal link appears here on an actual send]')
    .replace(/{{\s*contract_template:\d+\s*}}/gi, '[TEST — a real, unique contract link appears here on an actual send]')
    // Safety net matching Automation Engine.json's Prepare Email — strips
    // any OTHER unresolved "{{ }}" so a real send's preview matches what
    // actually goes out instead of risking the "undefined" corruption
    // n8n's own expression engine causes downstream on Send Test Email's
    // `={{ $json.body }}` field.
    .replace(/{{[^{}]*}}/g, '');
}
function escapeHtml(s) {
  return (s || '').toString()
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
}
// No tracking pixel here — a Test send is explicitly a no-side-effects
// dry run (see the module comment above), and the address typed into
// "Test email address" isn't necessarily the real contact's own email,
// so there's no legitimate contact to attribute an "opened" event to.
// Still converted to HTML so the preview matches what a real send (which
// IS html now) actually looks like.
const testBody = fill(meta._emailAction.action_config.body);
return [{
  json: {
    to: meta._testEmail, subject: '[TEST] ' + fill(meta._emailAction.action_config.subject), body: testBody,
    htmlBody: escapeHtml(testBody).replace(/\n/g, '<br>'),
  },
}];
